use cyberdeck_core::network::{parse_ipv4,Credentials,ProbePlan,service_name};
#[test]fn strict_ipv4_parser(){assert_eq!(parse_ipv4("192.168.1.2"),Some([192,168,1,2]));for text in ["1.2.3","1.2.3.4.5","256.1.1.1","1.2.-1.4","1.2.3.4x"]{assert_eq!(parse_ipv4(text),None);}}
#[test]fn credentials_bounded_and_redacted(){assert!(Credentials::new("lab","").is_ok());assert!(Credentials::new("lab","short").is_err());assert!(Credentials::new(&"s".repeat(33),"abcdefgh").is_err());let c=Credentials::new("lab","secret12").unwrap();assert!(!format!("{c:?}").contains("secret12"));}
#[test]fn targets_stay_in_subnet_and_are_bounded(){let p=ProbePlan::new([192,168,1,10],24,1,200).unwrap();assert!(p.addresses().len()<=16);assert!(!p.addresses().contains(&[192,168,1,10]));assert!(p.addresses().iter().all(|ip|ip[0..3]==[192,168,1]&&ip[3]>0&&ip[3]<255));}
#[test]fn small_subnet_avoids_network_broadcast(){let p=ProbePlan::new([10,0,0,6],30,1,16).unwrap();assert_eq!(p.addresses(),&[[10,0,0,5]]);assert!(ProbePlan::new([10,0,0,1],33,1,16).is_none());}
#[test]fn service_names_are_useful(){assert_eq!(service_name(22),"SSH");assert_eq!(service_name(443),"HTTPS");assert_eq!(service_name(65000),"TCP");}
#[test]fn dns_probe_requires_matching_response(){use cyberdeck_core::network::{dns_query,dns_response};let mut packet=dns_query(0x1234);assert!(packet.len()<64);assert_eq!(dns_response(&packet,0x1234),None);packet[2]=0x81;packet[3]=0x83;assert_eq!(dns_response(&packet,0x1234),Some(3));assert_eq!(dns_response(&packet,0x1235),None);assert_eq!(dns_response(&packet[..11],0x1234),None);}
